// Shared cut plan: every scene's lift and camera end, the rects the match cuts connect, and the handoffs, so both
// sides of every cut read the same numbers. Generated by plan.mjs from script/timing.json; edit freely (L.plan in the
// kit lib documents every key). Plan the cuts once timing.json exists; rebuild them if the timing changes.
//   scene          key        start    dur
//   01-hook        hook       0.00  +6.30
//   02-meet        meet       6.30  +5.90
//   03-url         url       12.20  +3.70
//   04-study       study     15.90  +5.45
//   05-build       build     21.35  +6.05
//   06-test        test      27.40  +5.40
//   07-reviews     reviews   32.80  +8.40
//   08-launch      launch    41.20  +4.30
//   09-cta         cta       45.50  +5.38
const L = require("../lib/reel-lib.cjs");
const timing = require("../../script/timing.json");

const P = L.plan(timing, {
  // vertical offset that centres each scene's art in the grid field (DESIGN.md 4)
  lift: { hook: 0, meet: 0, url: 0, study: 0, build: 0, test: 0, reviews: 0, launch: 0, cta: 0 },
  // where each scene's camera ends up (no scale push: the stage is already drawn 7% larger, see reel-lib STAGE_K)
  // (it eases there from its landing within L.SETTLE and holds); hold-cut sources end at { s: 1 }
  camEnd: {
    hook:     { s: 1, x: 0, y: -6 },
    meet:     { s: 1, x: 0, y: 0 },
    url:      { s: 1, x: 0, y: -6 },
    study:    { s: 1, x: 0, y: 0 },
    build:    { s: 1, x: 0, y: -6 },
    test:     { s: 1, x: 0, y: -4 },
    reviews:  { s: 1, x: 0, y: -6 },
    launch:   { s: 1, x: 0, y: -6 },
    cta:      { s: 1, x: 0, y: -4 },
  },
  // rects [x, y, w, h] in each scene's .lift that the cuts connect
  R: {
    hookTerm: [110, 430, 860, 600],     // Claude Code with the /replica- autocomplete (hook, beat A)
    hookOrig: [58, 480, 440, 640],      // the original booking app (hook, beat B)
    hookClone: [582, 480, 440, 640],    // your version, rebuilt part by part (+ SMS reminders)
    // the whole screen in .lift coords (the stage is drawn STAGE_K larger about 540, 805): the full-bleed README
    meetFull: [540 - 540 / L.STAGE_K, 805 - 805 / L.STAGE_K, 1080 / L.STAGE_K, 1920 / L.STAGE_K].map(L.r3),
    urlTerm: [58, 640, 964, 330],       // Claude Code: /replica-recon <url>
    studyTerm: [190, 350, 700, 220],    // the same session, logging what it reads (held into build)
    recon: [58, 600, 964, 600],         // replica/recon.md (held into build, then it grows into the build window)
    build: [58, 380, 964, 700],         // the build window (tabs: architecture, design, frontend, backend)
    test: [58, 360, 964, 880],          // replica-test, then replica-diff (compare slider)
    reviews: [58, 380, 964, 820],       // replica-entrepreneur
    launch: [58, 380, 964, 600],        // the landing page
    live: [290, 1110, 500, 68],         // LIVE ON YOUR DOMAIN plate -> the CTA's repo window
    ctaRepo: L.ctaRects(require("../../script/reel.json").cta).repo,
  },
  // match cuts: name: [from, to, rectA, rectB, t0, land]. cut = to's start (above); land snaps to the nearest beat
  // (script/cues.md lists them); keep each side 0.23-0.5 s and the cut near peak speed (f 0.35-0.6)
  hands: {
    h1: ["hook", "meet", "hookClone", "meetFull", 6.0, 6.572],
    h2: ["meet", "url", "meetFull", "urlTerm", 11.9, 12.45],
    h3: ["url", "study", "urlTerm", "studyTerm", 15.55, 16.185],
    h5: ["build", "test", "build", "test", 27.05, 27.888],
    h7: ["reviews", "launch", "reviews", "launch", 40.85, 41.508],
    h8: ["launch", "cta", "live", "ctaRepo", 45.15, 45.95],
  },
  // hold cuts (the same frame on both sides): [[from, to]]
  holds: [["study", "build"]],
  // lands are hand-picked: the beats where a side fits, else the nearest fit (h2, h8: no beat gives a 0.23-0.5 s in side)
  snap: false,
});

// reel-specific shared numbers (implode seeds, shared geometry) go next to the plan
// the implode seed (test -> reviews): the centre of the reviews window's top edge, where its outline starts drawing
const SEED7 = [540, 380.75];
module.exports = { ...P, SEED7 };
